'use strict';

const v31FinaleStyle=document.createElement('style');
v31FinaleStyle.textContent=`
.season-flow{max-width:900px;margin:0 auto}.season-flow-progress{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:18px}.season-flow-progress span{padding:9px 5px;border:1px solid #3b5053;border-radius:7px;color:#7f9491;font-size:9px;text-align:center;text-transform:uppercase}.season-flow-progress span.done{border-color:#718b55;color:#c7f36b}.season-flow-progress span.active{background:#c7f36b;color:#172921;border-color:#c7f36b;font-weight:800}.season-flow-card{padding:25px}.season-flow-hero{display:grid;grid-template-columns:auto 1fr auto;gap:18px;align-items:center}.season-flow-hero h1{color:var(--club-primary);font-size:50px}.season-flow-kits{display:flex;gap:13px}.season-flow-stats{display:grid;grid-template-columns:repeat(6,1fr);gap:7px;margin:22px 0}.season-flow-stats span,.finance-flow-grid span{padding:12px 9px;border-radius:7px;background:#102126;color:#829694;font-size:8px;text-transform:uppercase}.season-flow-stats b,.finance-flow-grid b{display:block;margin-top:6px;color:#eef5f1;font-size:17px;text-transform:none}.season-top-three{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0 22px}.season-top-three article,.retirement-flow-list article{padding:13px;border:1px solid #3a4f52;border-radius:8px;background:#102126}.season-top-three small{color:var(--club-primary)}.season-top-three .player-link{display:flex;align-items:center;gap:7px;margin:7px 0;font-size:13px}.season-top-three span{color:#91a5a2;font-size:10px}.retirement-flow-list{display:grid;gap:9px;margin:17px 0 22px}.retirement-flow-list article{display:grid;grid-template-columns:32px minmax(0,1fr) auto;gap:10px;align-items:center}.retirement-flow-list .flag-icon{width:28px}.retirement-flow-list b,.retirement-flow-list span{display:block}.retirement-flow-list span{margin-top:4px;color:#94a7a4;font-size:10px}.retirement-flow-list em{color:#e9c878;font-size:10px;font-style:normal;text-align:right}.finance-flow-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:18px 0}.finance-flow-grid .positive b{color:#bdec9f}.finance-flow-grid .negative b{color:#ffaaa2}.finance-flow-total{display:flex;justify-content:space-between;align-items:center;margin:15px 0 22px;padding:16px;border:1px solid #526669;border-radius:8px}.finance-flow-total b{font-size:22px;color:var(--club-primary)}.finance-flow-total.game-over b{color:#ff8f86}.season-flow-note{color:#9cafac;font-size:11px;line-height:1.6}.season-flow .primary{margin-top:10px}
@media(max-width:760px){.season-flow-progress{grid-template-columns:repeat(2,1fr)}.season-flow-card{padding:18px}.season-flow-hero{grid-template-columns:1fr}.season-flow-kits{justify-content:center}.season-flow-stats{grid-template-columns:repeat(2,1fr)}.season-top-three{grid-template-columns:1fr}.finance-flow-grid{grid-template-columns:1fr 1fr}.retirement-flow-list article{grid-template-columns:28px minmax(0,1fr)}.retirement-flow-list em{grid-column:2;text-align:left}}
`;
document.head.append(v31FinaleStyle);

const v31PlacementAwards={1:900,2:750,3:600,4:450,5:325,6:250};
function v31PlacementPrize(rank){return v31PlacementAwards[rank]||250}
function v31StageIndex(stage){return{summary:0,retirements:1,finance:2,complete:3}[stage]??0}
function v31CareerLine(player){const stats=sumStats(player);return{games:stats.games||0,goals:stats.goals||0}}
function v31RetirementCandidates(){
 const candidates=[];for(const player of[activeSave.keeper,...activeSave.squad]){ensurePlayerId(player);const nextAge=(player.age||0)+1,chance=retirementChance(nextAge);if(chance&&Math.random()<chance){const career=v31CareerLine(player),last=storedSeason(player,activeSave.seasonNumber);candidates.push({pid:player.pid,name:player.name,nation:player.nation,position:transferPosition(player),age:nextAge,games:last.games||0,goals:last.goals||0,careerGames:career.games,careerGoals:career.goals,keeper:Boolean(player.keeper)})}}return candidates
}
function v31ClubTopThree(){return ownSeasonRows(activeSave.seasonNumber).filter(row=>!row.player.keeper).sort((a,b)=>(b.stats.goals||0)-(a.stats.goals||0)||(b.stats.onTarget||0)-(a.stats.onTarget||0)||(b.rating||0)-(a.rating||0)||a.player.name.localeCompare(b.player.name)).slice(0,3).map(row=>({pid:row.player.pid,name:row.player.name,nation:row.player.nation,games:row.stats.games||0,goals:row.stats.goals||0}))}
function v31EnsureFinale(){
 if(!activeSave||activeSave.currentRound<10)return null;const season=activeSave.seasonNumber,snapshot=seasonSnapshot();if(!activeSave.seasonFinale||activeSave.seasonFinale.season!==season)activeSave.seasonFinale={season,stage:'summary',retirements:v31RetirementCandidates(),topThree:v31ClubTopThree(),createdAt:new Date().toISOString()};activeSave.seasonFinale.snapshot=snapshot;return activeSave.seasonFinale
}
function v31AwardPlacement(){
 const finale=v31EnsureFinale();if(!finale)return 0;const finance=ensureFinance(activeSave),amount=v31PlacementPrize(finale.snapshot.rank),key=`placement-${finale.season}`;bookCredit(key,`Ligaplatzierung · Platz ${finale.snapshot.rank}`,amount,'placement');finance.placementCredits=finance.placementCredits||{};finance.placementCredits[finale.season]=amount;return amount
}
function v31FinanceBreakdown(){
 const finale=v31EnsureFinale(),finance=ensureFinance(activeSave),season=finale.season,salary=Math.abs(finance.ledger.find(entry=>entry.key===`salary-${season}`)?.amount||payroll()),placement=finance.placementCredits?.[season]||v31PlacementPrize(finale.snapshot.rank),terms=typeof v26SponsorTerms==='undefined'?{}:v26SponsorTerms,sponsorFixed=terms[finance.sponsor.selectedId]?.fixed||0,sponsorBonus=Math.max(0,(finance.sponsor.paidAmount||0)-sponsorFixed),results=finance.resultCredits[season]||0,closing=finance.balance,before=closing-results-sponsorFixed-sponsorBonus-placement+salary;
 return{before,results,sponsorFixed,sponsorBonus,placement,salary,closing,gameOver:finance.gameOver}
}

const v30SettleAnnualPayrollV31=settleAnnualPayroll;
settleAnnualPayroll=function(){
 if(!activeSave||activeSave.currentRound<10)return v30SettleAnnualPayrollV31();const finance=ensureFinance(activeSave),season=activeSave.seasonNumber;v31AwardPlacement();v30SettleAnnualPayrollV31();finance.gameOver=finance.balance<0;finance.shortfall=Math.max(0,-finance.balance);finance.closingBalance=finance.balance;const finale=v31EnsureFinale(),snapshot=finale?.snapshot;if(snapshot)snapshot.finance={...(snapshot.finance||{}),resultCredits:finance.resultCredits[season]||0,sponsorCredits:finance.sponsor.paidAmount||0,placementCredits:finance.placementCredits?.[season]||0,salaries:payroll(),closingBalance:finance.balance,gameOver:finance.gameOver};if(finale)finale.finance=v31FinanceBreakdown();return finance.balance
};

const v30ProcessRetirementsV31=processRetirements;
processRetirements=function(){
 const planned=activeSave.pendingRetirements;if(!Array.isArray(planned))return v30ProcessRetirementsV31();const state=transferState();if(state.prepared)return;state.prepared=true;state.open=true;state.offers=createMarketOffers();state.retirements=[];
 for(const item of planned){const player=[activeSave.keeper,...activeSave.squad].find(entry=>entry?.pid===item.pid);if(!player)continue;player.retired=true;player.retiredAge=player.age;player.retiredAfterSeason=activeSave.seasonNumber-1;state.retirements.push({...item,age:player.age});archiveFormer(player,'Karriereende')}
 delete activeSave.pendingRetirements;normalizeLineup();syncLineupFromSquad()
};

function v31Progress(stage){const active=v31StageIndex(stage);return`<div class="season-flow-progress">${['Saisonbilanz','Karriereenden','Finanzen','Neue Saison'].map((label,index)=>`<span class="${index<active?'done':index===active?'active':''}">${label}</span>`).join('')}</div>`}
function v31SummaryHTML(finale){
 const s=finale.snapshot,kits=currentKits(),difference=s.gf-s.ga;return`${v31Progress('summary')}<section class="panel season-flow-card"><div class="season-flow-hero">${crestHTML(activeSave.club,kits)}<div><p class="eyebrow">SAISON ${s.number} ABGESCHLOSSEN</p><h1>${s.rank===1?'MEISTER!':`Platz ${s.rank}`}</h1><p class="season-flow-note">${escapeHTML(s.champion)} ist Meister der Sechserliga.</p></div><div class="season-flow-kits">${kitHTML(kits.home,'Heimtrikot')}${kitHTML(kits.away,'Auswärtstrikot')}</div></div><div class="season-flow-stats"><span>Spiele<b>${s.played}</b></span><span>Punkte<b>${s.pts}</b></span><span>Siege<b>${s.w}</b></span><span>Remis<b>${s.d}</b></span><span>Niederlagen<b>${s.l}</b></span><span>Tore<b>${s.gf}:${s.ga}</b></span><span>Tordifferenz<b>${difference>0?'+':''}${difference}</b></span></div><h2>Top 3 Torschützen deines Kaders</h2><div class="season-top-three">${finale.topThree.map((player,index)=>`<article><small>#${index+1}</small><button class="player-link" data-final-player="${escapeHTML(player.pid)}">${flagSVG(player.nation)} ${escapeHTML(player.name)}</button><span>${player.goals} Tore · ${player.games} Spiele</span></article>`).join('')||'<p class="help">Keine Torschützen vorhanden.</p>'}</div><button class="primary" data-finale-stage="retirements">Weiter: Karriereenden <span>↗</span></button></section>`
}
function v31RetirementsHTML(finale){return`${v31Progress('retirements')}<section class="panel season-flow-card"><p class="eyebrow">PERSONALENTSCHEIDUNGEN</p><h1>Karriereenden</h1><p class="season-flow-note">Diese Entscheidungen wurden einmalig berechnet und bleiben auch nach einem Neuladen unverändert.</p>${finale.retirements.length?`<div class="retirement-flow-list">${finale.retirements.map(player=>`<article>${flagSVG(player.nation)}<div><button class="player-link" data-final-player="${escapeHTML(player.pid)}">${escapeHTML(player.name)}</button><span>${escapeHTML(player.position)} · ${player.age} Jahre</span></div><em>Letzte Saison: ${player.games} Sp. · ${player.goals} Tore<br>Karriere: ${player.careerGames} Sp. · ${player.careerGoals} Tore</em></article>`).join('')}</div>`:'<div class="panel"><h2>Keine Karriereenden</h2><p class="help">In diesem Jahr beendet kein Spieler seine Karriere.</p></div>'}<button class="primary" data-finale-stage="finance">Weiter: Finanzabschluss <span>↗</span></button></section>`}
function v31FinanceHTML(finale){
 const f=finale.finance||v31FinanceBreakdown(),next=finale.season+1;return`${v31Progress('finance')}<section class="panel season-flow-card"><p class="eyebrow">FINANZABSCHLUSS · SAISON ${finale.season}</p><h1>${f.gameOver?'Zahlungsunfähig.':'Saison finanziert.'}</h1><div class="finance-flow-grid"><span>Vor Abschluss<b>${f.before}</b></span><span>Ergebnisprämien<b>+${f.results}</b></span><span>Sponsorfixum<b>+${f.sponsorFixed}</b></span><span class="positive">Sponsorbonus<b>+${f.sponsorBonus}</b></span><span class="positive">Platz ${finale.snapshot.rank}<b>+${f.placement}</b></span><span class="negative">Jahresgehälter<b>−${f.salary}</b></span></div><div class="finance-flow-total ${f.gameOver?'game-over':''}"><span>Kontostand nach Abschluss</span><b>${f.closing} Credits</b></div><p class="season-flow-note">Die Platzierungsprämie wurde vor den Jahresgehältern verbucht. Jede Zahlung kann pro Saison nur einmal erfolgen.</p><button class="primary" data-finale-stage="${f.gameOver?'gameover':'complete'}">${f.gameOver?'Game Over ansehen':`Saison ${next} beginnen`} <span>↗</span></button></section>`
}
function v31RenderFinale(){
 const finale=v31EnsureFinale();if(!finale)return false;if(finale.stage==='gameover'){renderGameOver();document.querySelectorAll('footer span:first-child').forEach(element=>element.textContent='SECHSER / PROTOTYP 31');return true}const html=finale.stage==='retirements'?v31RetirementsHTML(finale):finale.stage==='finance'?v31FinanceHTML(finale):v31SummaryHTML(finale);clubCenter.innerHTML=`<section class="intro"><div><p class="eyebrow">SAISONABSCHLUSS</p><h1>${escapeHTML(activeSave.club)}</h1></div><p class="center-subtitle">Saison ${finale.season}</p></section><div class="season-flow">${html}</div><footer><span>SECHSER / PROTOTYP 31</span><span>Saison ${finale.season}</span></footer>`;clubCenter.querySelectorAll('[data-finale-stage]').forEach(button=>button.onclick=()=>v31SetStage(button.dataset.finaleStage));clubCenter.querySelectorAll('[data-final-player]').forEach(button=>button.onclick=()=>openPlayerCard(button.dataset.finalPlayer));return true
}
function v31SetStage(stage){
 const finale=v31EnsureFinale();if(!finale)return false;if(stage==='complete'){activeSave.pendingRetirements=structuredClone(finale.retirements);activeSave.seasonFinaleArchive=activeSave.seasonFinaleArchive||[];activeSave.seasonFinaleArchive.push(structuredClone(finale));activeSave.seasonFinale=null;saveCurrent();startNextSeason();return true}if(!['summary','retirements','finance','gameover'].includes(stage))return false;finale.stage=stage;saveCurrent();renderCenter();window.scrollTo(0,0);return true
}

const v30RenderCenterV31=renderCenter;
renderCenter=function(){if(activeSave?.currentRound>=10){settleAnnualPayroll();saveCurrent();v31RenderFinale();return}const result=v30RenderCenterV31();document.querySelectorAll('footer span:first-child').forEach(element=>element.textContent='SECHSER / PROTOTYP 31');return result};

drawSlots();document.querySelectorAll('footer span:first-child').forEach(element=>element.textContent='SECHSER / PROTOTYP 31');
